steps.css:
body {
  max-width: 400px;
  margin: 30px auto;
  padding: 26px;
  font-family: Arial, sans-serif;
  color: #203853;
  background: #edf8f3;
  border: 2px solid #a6d8c0;
  border-radius: 20px;
  text-align: center;
}

h1 { color: #246b55; }
label { display: block; margin: 16px 0 6px; }
input {
  width: 110px;
  padding: 10px;
  border: 2px solid #79b79b;
  border-radius: 8px;
  font-size: 1.1rem;
  text-align: center;
}
button {
  margin: 8px 4px;
  padding: 10px 16px;
  color: white;
  background: #28775b;
  border: 0;
  border-radius: 8px;
  cursor: pointer;
}
button:hover { background: #195640; }
p { min-height: 1.5em; font-weight: bold; }

